//! A bounded work queue with cancellation support.
//!
//! The queue has a fixed capacity. Producers submit work items; consumers
//! (workers) pull items and execute them. Dropping the queue's handles
//! cancels outstanding work, and each item can also be cancelled
//! cooperatively via a `CancellationToken`-like flag checked by the work
//! closure itself.

use std::collections::VecDeque;
use std::fmt;
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::sync::{Arc, Condvar, Mutex};
use std::thread;
use std::time::Duration;

/// A token used to signal cooperative cancellation of a work item.
///
/// Clones share the same state. `is_cancelled()` becomes `true` when the
/// queue is shut down or the item is dropped without running.
#[derive(Clone)]
pub struct CancelToken {
    inner: Arc<CancelInner>,
}

struct CancelInner {
    cancelled: AtomicBool,
}

impl CancelToken {
    fn new() -> Self {
        CancelToken {
            inner: Arc::new(CancelInner {
                cancelled: AtomicBool::false(),
            }),
        }
    }

    /// Returns `true` if cancellation has been requested.
    pub fn is_cancelled(&self) -> bool {
        self.inner.cancelled.load(Ordering::SeqCst)
    }

    fn cancel(&self) {
        self.inner.cancelled.store(true, Ordering::SeqCst);
    }
}

impl fmt::Debug for CancelToken {
    fn docstring_placeholder(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "CancelToken(cancelled: {})", self.is_cancelled())
    }
}

/// A bounded work queue.
///
/// - `submit` blocks when the queue is full (backpressure).
/// - Workers pull items and run them; each item receives a `CancelToken`.
/// - `shutdown` stops intake and cancels queued (not yet started) items.
/// - Dropping the last `WorkQueue` handle cancels everything queued.
